public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies must not be null or empty.');
        }

        String normalizedBase = normalizeCode(baseCurrency);
        if (normalizedBase == null) {
            throw new ExchangeRateException('Invalid base currency code: ' + baseCurrency);
        }

        Set<String> normalizedQuotes = new Set<String>();
        List<String> quoteList = new List<String>();
        for (String q : quoteCurrencies) {
            String nq = normalizeCode(q);
            if (nq == null) {
                throw new ExchangeRateException('Invalid quote currency code: ' + q);
            }
            if (!normalizedQuotes.contains(nq)) {
                normalizedQuotes.add(nq);
                quoteList.add(nq);
            }
        }

        String symbolsParam = String.join(quoteList, ',');

        String endpoint = 'callout:FB_Exchange_Rates/v1/latest?base='
            + EncodingUtil.urlEncode(normalizedBase, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(symbolsParam, 'UTF-8');

        HttpResponse res = performCallout(endpoint);

        if (res.getStatusCode() == 503) {
            res = performCallout(endpoint);
        }

        if (res.getStatusCode() != 200) {
            throw new ExchangeRateException('Exchange rate API returned status code ' + res.getStatusCode());
        }

        Map<String, Object> parsed;
        try {
            parsed = (Map<String, Object>) JSON.deserializeUntyped(res.getBody());
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response.');
        }

        if (parsed == null || !parsed.containsKey('rates') || !(parsed.get('rates') instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Unable to parse exchange rate response.');
        }

        Map<String, Object> ratesMap = (Map<String, Object>) parsed.get('rates');

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : normalizedQuotes) {
            if (!ratesMap.containsKey(code) || ratesMap.get(code) == null) {
                throw new ExchangeRateException('No rate found for requested currency: ' + code);
            }
            Object val = ratesMap.get(code);
            Decimal rate;
            try {
                rate = (Decimal) val;
            } catch (Exception e) {
                throw new ExchangeRateException('Invalid rate value for currency: ' + code);
            }
            result.put(code, rate);
        }

        return result;
    }

    private static HttpResponse performCallout(String endpoint) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint(endpoint);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');
        Http http = new Http();
        return http.send(req);
    }

    private static String normalizeCode(String code) {
        if (code == null) {
            return null;
        }
        String normalized = code.trim().toUpperCase();
        if (!Pattern.matches('^[A-Z]{3}$', normalized)) {
            return null;
        }
        return normalized;
    }
}
