public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {

        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required.');
        }

        Schema.SObjectType sObjType = Schema.getGlobalDescribe().get(objectApiName.toLowerCase());
        if (sObjType == null) {
            throw new SearchException('Object "' + objectApiName + '" does not exist.');
        }

        Schema.DescribeSObjectResult objDescribe = sObjType.getDescribe();
        if (!objDescribe.isAccessible()) {
            throw new SearchException('Object "' + objectApiName + '" is not accessible.');
        }

        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // Validate + dedupe select fields (always include Id)
        Set<String> selectFieldsLower = new Set<String>();
        List<String> selectFieldsApi = new List<String>();
        selectFieldsLower.add('id');
        selectFieldsApi.add('Id');

        for (String f : fields) {
            if (String.isBlank(f)) {
                throw new SearchException('Field name cannot be blank.');
            }
            Schema.DescribeFieldResult fd = getFieldDescribe(fieldMap, f, objectApiName);
            if (!fd.isAccessible()) {
                throw new SearchException('Field "' + f + '" is not accessible.');
            }
            String lower = fd.getName().toLowerCase();
            if (!selectFieldsLower.contains(lower)) {
                selectFieldsLower.add(lower);
                selectFieldsApi.add(fd.getName());
            }
        }

        // Validate filters
        List<String> whereClauses = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            for (String key : filters.keySet()) {
                if (String.isBlank(key)) {
                    throw new SearchException('Filter field name cannot be blank.');
                }
                Schema.DescribeFieldResult fd = getFieldDescribe(fieldMap, key, objectApiName);
                if (!fd.isAccessible()) {
                    throw new SearchException('Field "' + key + '" is not accessible.');
                }
                if (!fd.isFilterable()) {
                    throw new SearchException('Field "' + key + '" cannot be filtered.');
                }
                Object value = filters.get(key);
                String literal = formatValue(value, fd.getType());
                whereClauses.add(fd.getName() + ' = ' + literal);
            }
        }

        // Validate order by
        String orderByClause = '';
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult fd = getFieldDescribe(fieldMap, orderByField, objectApiName);
            if (!fd.isAccessible()) {
                throw new SearchException('Field "' + orderByField + '" is not accessible.');
            }
            if (!fd.isSortable()) {
                throw new SearchException('Field "' + orderByField + '" cannot be sorted.');
            }
            orderByClause = ' ORDER BY ' + fd.getName() + ' ASC';
        }

        String query = 'SELECT ' + String.join(selectFieldsApi, ', ') +
            ' FROM ' + objDescribe.getName();

        if (!whereClauses.isEmpty()) {
            query += ' WHERE ' + String.join(whereClauses, ' AND ');
        }

        query += orderByClause;
        query += ' WITH SECURITY_ENFORCED';
        query += ' LIMIT ' + String.valueOf(maxRows);

        try {
            return Database.query(query);
        } catch (System.QueryException qe) {
            throw new SearchException('Error executing search: ' + qe.getMessage());
        }
    }

    private static Schema.DescribeFieldResult getFieldDescribe(Map<String, Schema.SObjectField> fieldMap, String fieldName, String objectApiName) {
        Schema.SObjectField field = fieldMap.get(fieldName.toLowerCase());
        if (field == null) {
            throw new SearchException('Field "' + fieldName + '" does not exist on object "' + objectApiName + '".');
        }
        return field.getDescribe();
    }

    private static String formatValue(Object value, Schema.DisplayType type) {
        if (value == null) {
            return 'NULL';
        }

        switch on type {
            when BOOLEAN {
                if (value instanceof Boolean) {
                    return String.valueOf((Boolean) value);
                }
                return String.valueOf(Boolean.valueOf(String.valueOf(value)));
            }
            when INTEGER, DOUBLE, CURRENCY, PERCENT, LONG {
                if (value instanceof String) {
                    // validate numeric
                    Decimal d = Decimal.valueOf((String) value);
                    return String.valueOf(d);
                }
                return String.valueOf(value);
            }
            when DATE {
                Date d;
                if (value instanceof Date) {
                    d = (Date) value;
                } else {
                    d = Date.valueOf(String.valueOf(value));
                }
                return d.year() + '-' + pad(d.month()) + '-' + pad(d.day());
            }
            when DATETIME {
                Datetime dt;
                if (value instanceof Datetime) {
                    dt = (Datetime) value;
                } else {
                    dt = Datetime.valueOf(String.valueOf(value));
                }
                return dt.formatGmt('yyyy-MM-dd\'T\'HH:mm:ss\'Z\'');
            }
            when else {
                String s = String.valueOf(value);
                return '\'' + String.escapeSingleQuotes(s) + '\'';
            }
        }
    }

    private static String pad(Integer i) {
        return i < 10 ? '0' + i : String.valueOf(i);
    }
}
