public class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON: ' + e.getMessage());
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Body is not a JSON object');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        Order order = new Order();

        Object numberObj = root.get('number');
        if (numberObj == null || !(numberObj instanceof String) || String.isBlank((String) numberObj)) {
            throw new PayloadException('Missing or blank number');
        }
        order.orderNumber = (String) numberObj;

        Object dateObj = root.get('date');
        if (dateObj != null) {
            try {
                order.orderDate = Date.valueOf((String) dateObj);
            } catch (Exception e) {
                throw new PayloadException('Invalid date format');
            }
        }

        Object currencyObj = root.get('currency');
        if (currencyObj != null) {
            order.currencyCode = (String) currencyObj;
        }

        Object customerObj = root.get('customer');
        if (customerObj instanceof Map<String, Object>) {
            Map<String, Object> customerMap = (Map<String, Object>) customerObj;
            Object emailObj = customerMap.get('email');
            if (emailObj != null) {
                order.customerEmail = (String) emailObj;
            }
        }

        order.lines = new List<Line>();
        Decimal total = 0;

        Object linesObj = root.get('lines');
        if (linesObj != null) {
            if (!(linesObj instanceof List<Object>)) {
                throw new PayloadException('lines must be an array');
            }
            List<Object> lineList = (List<Object>) linesObj;
            for (Object lo : lineList) {
                if (!(lo instanceof Map<String, Object>)) {
                    throw new PayloadException('line must be an object');
                }
                Map<String, Object> lm = (Map<String, Object>) lo;

                Line line = new Line();

                Object skuObj = lm.get('sku');
                if (skuObj == null || !(skuObj instanceof String) || String.isBlank((String) skuObj)) {
                    throw new PayloadException('Missing sku on line');
                }
                line.sku = (String) skuObj;

                Object qtyObj = lm.get('quantity');
                if (qtyObj == null) {
                    throw new PayloadException('Missing quantity on line');
                }
                Integer qty;
                try {
                    qty = Integer.valueOf(qtyObj);
                } catch (Exception e) {
                    throw new PayloadException('Invalid quantity on line');
                }
                if (qty == null || qty <= 0) {
                    throw new PayloadException('Non-positive quantity on line');
                }
                line.quantity = qty;

                Object priceObj = lm.get('unitPrice');
                if (priceObj == null) {
                    throw new PayloadException('Missing unitPrice on line');
                }
                Decimal unitPrice;
                try {
                    unitPrice = parseDecimal(priceObj);
                } catch (Exception e) {
                    throw new PayloadException('Invalid unitPrice on line');
                }
                if (unitPrice == null || unitPrice < 0) {
                    throw new PayloadException('Negative unitPrice on line');
                }
                line.unitPrice = unitPrice;

                Object discObj = lm.get('discount');
                Decimal discount = 0;
                if (discObj != null) {
                    try {
                        discount = parseDecimal(discObj);
                    } catch (Exception e) {
                        throw new PayloadException('Invalid discount on line');
                    }
                    if (discount == null) {
                        discount = 0;
                    }
                }
                line.discount = discount;

                Decimal rawTotal = line.quantity * line.unitPrice * (1 - line.discount);
                line.lineTotal = rawTotal.setScale(2, System.RoundingMode.HALF_UP);

                total += line.lineTotal;

                order.lines.add(line);
            }
        }

        order.total = total;

        return order;
    }

    private static Decimal parseDecimal(Object o) {
        if (o instanceof Decimal) {
            return (Decimal) o;
        }
        if (o instanceof Integer) {
            return Decimal.valueOf((Integer) o);
        }
        if (o instanceof Double) {
            return Decimal.valueOf(String.valueOf(o));
        }
        if (o instanceof String) {
            return Decimal.valueOf((String) o);
        }
        throw new PayloadException('Cannot parse number');
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines != null ? order.lines.size() : 0);
        ack.put('total', order.total);
        return JSON.serialize(ack);
    }
}
