public class OpportunityPipelineHandler {

    // Recursion guard: prevents re-entering this logic when the Account update below
    // cascades through AccountTrigger -> updates Opportunity.FB_Account_Rating__c ->
    // re-fires OpportunityTrigger within the same call stack.
    private static Boolean isUpdatingAccounts = false;

    public static void handle(List<Opportunity> newRecords, Map<Id, Opportunity> oldMap,
                               Boolean isDelete, Boolean isUndelete) {
        if (isUpdatingAccounts) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();

        if (newRecords != null) {
            for (Opportunity o : newRecords) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        }

        if (oldMap != null) {
            for (Opportunity o : oldMap.values()) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        recalculate(accountIds);
    }

    private static void recalculate(Set<Id> accountIds) {
        Map<Id, Double> sumMap = new Map<Id, Double>();
        Map<Id, Integer> countMap = new Map<Id, Integer>();

        // Default every affected account to 0 / 0 so that accounts whose
        // last open opportunity disappeared are correctly reset.
        for (Id accId : accountIds) {
            sumMap.put(accId, 0.0);
            countMap.put(accId, 0);
        }

        for (AggregateResult ar : [
            SELECT AccountId acc, SUM(Amount) amt, COUNT(Id) cnt
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('acc');
            Object amtObj = ar.get('amt');
            Double amt = amtObj == null ? 0.0 : (Double) amtObj;
            Integer cnt = (Integer) ar.get('cnt');
            sumMap.put(accId, amt);
            countMap.put(accId, cnt);
        }

        List<Account> toUpdate = new List<Account>();
        for (Id accId : accountIds) {
            toUpdate.add(new Account(
                Id = accId,
                FB_Open_Pipeline__c = sumMap.get(accId),
                FB_Open_Opportunities__c = countMap.get(accId)
            ));
        }

        isUpdatingAccounts = true;
        try {
            update toUpdate;
        } finally {
            isUpdatingAccounts = false;
        }
    }
}
