public class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        DateTime nonErrorCutoff = DateTime.now().addDays(-30);
        DateTime errorCutoff = DateTime.now().addDays(-180);

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c != 'ERROR' AND CreatedDate < :nonErrorCutoff)
               OR (Level__c = 'ERROR' AND CreatedDate < :errorCutoff)
        ];

        if (!logsToDelete.isEmpty()) {
            delete logsToDelete;
        }
    }

    public static Id scheduleNightly() {
        String cronExpression = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
