                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = Date.today().addDays(1),
                Priority = 'High'
            );
            uow.registerNew(t);

            hasWork = true;
        }

        if (hasWork) {
            uow.commitWork();
        }
    }
