        }

        if (contactsToUpdate.isEmpty()) {
            return errors;
        }

        List<Database.SaveResult> results = Database.update(contactsToUpdate, false);

        for (Database.SaveResult sr : results) {
            if (!sr.isSuccess()) {
                String msg = sr.getErrors().isEmpty() ? 'Unknown error' : sr.getErrors()[0].getMessage();
                errors.put(sr.getId(), msg);
            }
        }

        return errors;
    }
}
