public with sharing class FollowUpTaskService {

    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // Bulk query the opportunities we need data from
        List<Opportunity> opportunities = [
            SELECT Id, Name, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        // Build tasks in parallel with a list of corresponding opportunity Ids
        List<Task> tasksToInsert = new List<Task>();
        List<Id> correspondingOppIds = new List<Id>();

        Date followUpDate = Date.today().addDays(7);

        for (Opportunity opp : opportunities) {
            Task t = new Task();
            t.WhatId = opp.Id;
            t.OwnerId = opp.OwnerId;
            t.Subject = 'Follow up: ' + opp.Name;
            t.ActivityDate = followUpDate;
            t.Status = 'Not Started';
            t.Priority = 'Normal';

            tasksToInsert.add(t);
            correspondingOppIds.add(opp.Id);
        }

        // Any opportunity Id passed in but not found in the query (e.g. deleted/invalid)
        // should also be reported as failed.
        Set<Id> foundOppIds = new Set<Id>();
        for (Opportunity opp : opportunities) {
            foundOppIds.add(opp.Id);
        }
        for (Id oppId : opportunityIds) {
            if (!foundOppIds.contains(oppId)) {
                failedOpportunityIds.add(oppId);
            }
        }

        if (tasksToInsert.isEmpty()) {
            return failedOpportunityIds;
        }

        // Single bulk DML call with partial success so one bad Task
        // (e.g. rejected by a validation rule) doesn't block the others.
        List<Database.SaveResult> saveResults = Database.insert(tasksToInsert, false);

        for (Integer i = 0; i < saveResults.size(); i++) {
            if (!saveResults[i].isSuccess()) {
                failedOpportunityIds.add(correspondingOppIds[i]);
            }
        }

        return failedOpportunityIds;
    }
}
```

