trigger CaseTrigger on Case (after update) {
    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);
        if (c.IsClosed && !oldCase.IsClosed && c.ContactId != null) {
            // Guard against the governor limit of 50 queueable jobs per transaction.
            // Agents can close up to 200 cases in one bulk operation, so if we ever
            // exceed the limit we skip enqueueing rather than throwing a hard error
            // that would roll back the whole DML operation for all cases.
            if (Limits.getQueueableJobs() < Limits.getLimitQueueableJobs()) {
                System.enqueueJob(new CaseSurveyJob(c.Id));
            } else {
                // Could not enqueue additional jobs this transaction; log for follow-up.
                System.debug(LoggingLevel.WARN,
                    'Queueable job limit reached, skipping survey task for Case ' + c.Id);
            }
        }
    }
}
