```apex
/**
 * Sends renewal reminder emails to Opportunity owners.
 *
 * IMPORTANT: Messaging.sendEmail is limited to 10 calls per transaction.
 * To stay within that limit while supporting up to 200 opportunities per
 * invocation, emails are batched into chunks and each chunk is sent with a
 * single Messaging.sendEmail(List<SingleEmailMessage>) call. This also means
 * a failure for one recipient (e.g. no email, bounced address) does not
 * prevent the other emails in the same batch from being sent, because
 * Messaging.sendEmail with a list returns a SendEmailResult per message
 * rather than throwing on the first failure.
 */
public with sharing class RenewalReminderService {

    // Max number of Messaging.sendEmail calls allowed per transaction.
    private static final Integer MAX_SEND_EMAIL_CALLS = 10;

    public static Integer sendReminders(List<Id> opportunityIds) {
        Integer sentCount = 0;

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return sentCount;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
            AND OwnerId != null
        ];

        if (opportunities.isEmpty()) {
            return sentCount;
        }

        // Determine chunk size so that we never exceed MAX_SEND_EMAIL_CALLS calls.
        Integer chunkSize = Integer.valueOf(
            Math.ceil((Decimal) opportunities.size() / MAX_SEND_EMAIL_CALLS)
        );
        if (chunkSize < 1) {
            chunkSize = 1;
        }

        List<Messaging.SingleEmailMessage> currentBatch = new List<Messaging.SingleEmailMessage>();

        for (Integer i = 0; i < opportunities.size(); i++) {
            Opportunity opp = opportunities[i];
            currentBatch.add(buildEmail(opp));

            Boolean isLastOpp = (i == opportunities.size() - 1);
            Boolean batchFull = (currentBatch.size() == chunkSize);

            if (batchFull || isLastOpp) {
                sentCount += sendBatch(currentBatch);
                currentBatch = new List<Messaging.SingleEmailMessage>();
            }
        }

        return sentCount;
    }

    private static Messaging.SingleEmailMessage buildEmail(Opportunity opp) {
        Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
        mail.setTargetObjectId(opp.OwnerId);
        mail.setSaveAsActivity(false);
        mail.setSubject('Renewal due: ' + opp.Name);

        String closeDateStr = (opp.CloseDate != null)
            ? opp.CloseDate.format()
            : 'an unspecified date';

        mail.setPlainTextBody(
            'This is a reminder that the opportunity "' + opp.Name +
            '" is due for renewal on ' + closeDateStr +
            '. Please review it and take the necessary action.'
        );

        return mail;
    }

    private static Integer sendBatch(List<Messaging.SingleEmailMessage> batch) {
        Integer successCount = 0;

        if (batch.isEmpty()) {
            return successCount;
        }

        Messaging.SendEmailResult[] results = Messaging.sendEmail(batch, false);

        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                successCount++;
            }
        }

        return successCount;
    }
}
```

I changed one key thing about your approach: querying **all 2.3 million contacts** into a map at the top of the handler is not bulk-safe — it will blow past heap size limits (6/12MB) and query row limits (50,000 rows) almost immediately, regardless of how few accounts are actually in the trigger batch. "One query" is good practice, but it must be **scoped to the accounts in the current trigger context**, not the whole org. So I query only `Contact` rows `WHERE AccountId IN :changedAccountIds` — still exactly one SOQL query, no queries in loops, but bounded by the (max 200) accounts in this batch rather than the entire Contact table.

