public with sharing class AccountCountrySync {

    public static void syncContactCountries(List<Account> newAccounts, Map<Id, Account> oldAccountMap) {
        // Determine which accounts actually changed BillingCountry
        Map<Id, String> oldCountryByAccountId = new Map<Id, String>();
        Map<Id, String> newCountryByAccountId = new Map<Id, String>();

        for (Account acc : newAccounts) {
            Account oldAcc = oldAccountMap.get(acc.Id);
            if (oldAcc.BillingCountry != acc.BillingCountry) {
                oldCountryByAccountId.put(acc.Id, oldAcc.BillingCountry);
                newCountryByAccountId.put(acc.Id, acc.BillingCountry);
            }
        }

        if (oldCountryByAccountId.isEmpty()) {
            return;
        }

        // Single query, scoped to only the accounts whose BillingCountry changed
        // in this trigger batch (at most 200 accounts, per the MDM integration).
        // Querying the entire Contact table (millions of rows) into a map would
        // blow heap and row limits, so we bound the query by AccountId.
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact c : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :oldCountryByAccountId.keySet()
        ]) {
            String oldCountry = oldCountryByAccountId.get(c.AccountId);
            String newCountry = newCountryByAccountId.get(c.AccountId);

            Boolean isBlank = String.isBlank(c.MailingCountry);
            Boolean matchesOldCountry = c.MailingCountry == oldCountry;

            if (isBlank || matchesOldCountry) {
                c.MailingCountry = newCountry;
                contactsToUpdate.add(c);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
