import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    @api recordId;

    isLoading = false;
    opportunities;
    error;
    hasLoaded = false;

    connectedCallback() {
        this.loadOpportunities();
    }

    loadOpportunities() {
        this.isLoading = true;
        this.error = undefined;
        getOpenOpportunities({ accountId: this.recordId })
            .then((result) => {
                this.opportunities = result;
                this.error = undefined;
            })
            .catch((error) => {
                this.error = error;
                this.opportunities = undefined;
            })
            .finally(() => {
                this.isLoading = false;
            });
    }

    get hasError() {
        return !this.isLoading && this.error;
    }

    get hasOpportunities() {
        return !this.isLoading && !this.error && this.opportunities && this.opportunities.length > 0;
    }

    get isEmpty() {
        return !this.isLoading && !this.error && this.opportunities && this.opportunities.length === 0;
    }

    get errorMessage() {
        return this.error && this.error.body && this.error.body.message
            ? this.error.body.message
            : 'Unknown error';
    }

    handleRetry() {
        this.loadOpportunities();
    }
}
