    handleSubmit() {
        const editors = Array.from(
            this.template.querySelectorAll('c-line-item-editor')
        );

        let allValid = true;
        editors.forEach((editor) => {
            const valid = editor.validate();
            if (!valid) {
                allValid = false;
            }
        });

        if (allValid) {
            this.showError = false;
            const lines = editors.map((editor) => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines }
                })
            );
        } else {
            this.showError = true;
        }
    }
}
