import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const FREE_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        const field = event.target.dataset.field;
        this[field] = event.detail.value;
    }

    async handleRegister() {
        const inputs = this.template.querySelectorAll('lightning-input');
        const emailInput = this.template.querySelector('[data-field="email"]');

        if (emailInput) {
            const domain = (this.email || '').split('@')[1];
            if (domain && FREE_DOMAINS.includes(domain.toLowerCase())) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        let allValid = true;
        inputs.forEach((input) => {
            const valid = input.reportValidity();
            if (!valid) {
                allValid = false;
            }
        });

        if (!allValid) {
            return;
        }

        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message: error.body.message,
                    variant: 'error'
                })
            );
        }
    }
}
