import { LightningElement, api, track } from 'lwc';

let uid = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = val || [];
        if (!this._activeValue && this._options.length > 0) {
            this._activeValue = this._value || this._options[0].value;
        }
    }

    _value = '';
    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        this._activeValue = val || (this._options.length > 0 ? this._options[0].value : '');
    }

    @track _activeValue = '';

    baseId = `status-listbox-${++uid}`;

    get computedOptions() {
        return this._options.map((opt, index) => {
            const isSelected = opt.value === this._value;
            return {
                value: opt.value,
                label: opt.label,
                id: `${this.baseId}-opt-${index}`,
                index,
                ariaSelected: isSelected ? 'true' : 'false',
                className: isSelected ? 'option selected' : 'option'
            };
        });
    }

    get activeDescendant() {
        const idx = this._options.findIndex(opt => opt.value === this._activeValue);
        if (idx === -1) {
            return undefined;
        }
        return `${this.baseId}-opt-${idx}`;
    }

    get activeIndex() {
        const idx = this._options.findIndex(opt => opt.value === this._activeValue);
        return idx === -1 ? 0 : idx;
    }

    handleKeyDown(event) {
        const key = event.key;
        const lastIndex = this._options.length - 1;
        if (lastIndex < 0) {
            return;
        }
        let currentIndex = this.activeIndex;

        switch (key) {
            case 'ArrowDown':
                event.preventDefault();
                currentIndex = Math.min(currentIndex + 1, lastIndex);
                this._activeValue = this._options[currentIndex].value;
                break;
            case 'ArrowUp':
                event.preventDefault();
                currentIndex = Math.max(currentIndex - 1, 0);
                this._activeValue = this._options[currentIndex].value;
                break;
            case 'Home':
                event.preventDefault();
                this._activeValue = this._options[0].value;
                break;
            case 'End':
                event.preventDefault();
                this._activeValue = this._options[lastIndex].value;
                break;
            case 'Enter':
                event.preventDefault();
                this.selectOption(this._activeValue);
                break;
            case ' ':
                event.preventDefault();
                this.selectOption(this._activeValue);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const value = event.currentTarget.dataset.value;
        this._activeValue = value;
        this.selectOption(value);
    }

    selectOption(value) {
        if (value === this._value) {
            return;
        }
        this._value = value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value }
            })
        );
    }
}
