        this._items = (value || []).map((t) => ({ ...t }));
    }

    get upperHeading() {
        return this.heading ? this.heading.toUpperCase() : '';
    }

    get items() {
        return this._items;
    }

    get remaining() {
        return this._items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const trimmed = (this.newLabel || '').trim();
        if (!trimmed) {
            return;
        }
        this._items = [
            ...this._items,
            { id: `new-${this.nextId++}`, label: trimmed, done: false }
        ];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label: trimmed } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this._items = this._items.map((t) =>
            t.id === id ? { ...t, done: !t.done } : t
        );
    }
}
