public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // Query 1: existing primary affiliations for these contacts
        Map<Id, npe5__Affiliation__c> primaryAfflByContact = new Map<Id, npe5__Affiliation__c>();
        for (npe5__Affiliation__c affl : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c, npe5__Primary__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
            AND npe5__Primary__c = true
        ]) {
            primaryAfflByContact.put(affl.npe5__Contact__c, affl);
        }

        // Query 2: contacts themselves (to confirm existence / household context, not strictly
        // required for the update but keeps us within the 2-query budget if needed later)
        Map<Id, Contact> contactsById = new Map<Id, Contact>([
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]);

        List<npe5__Affiliation__c> toInsert = new List<npe5__Affiliation__c>();

        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (orgId == null || !contactsById.containsKey(contactId)) {
                continue;
            }

            npe5__Affiliation__c existingPrimary = primaryAfflByContact.get(contactId);

            // Already the primary affiliation for this org - nothing to do.
            if (existingPrimary != null
                && existingPrimary.npe5__Organization__c == orgId
                && existingPrimary.npe5__Status__c == 'Current') {
                continue;
            }

            npe5__Affiliation__c newAffl = new npe5__Affiliation__c(
                npe5__Contact__c = contactId,
                npe5__Organization__c = orgId,
                npe5__Status__c = 'Current',
                npe5__Primary__c = true,
                npe5__StartDate__c = System.today()
            );
            toInsert.add(newAffl);
        }

        if (!toInsert.isEmpty()) {
            // Single DML. NPSP's Affiliation TDTM (AFFL_Affiliations_TDTM) automatically:
            // - sets any prior primary affiliation for the contact to Former, non-primary,
            //   with an EndDate of today
            // - updates Contact.npsp__Primary_Affiliation__c to point to the new organization
            // The contact's AccountId (household) is untouched by this operation.
            insert toInsert;
        }
    }
}
