public class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id is required.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('Percentage map must not be null or empty.');
        }

        Decimal total = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('Percentage for GAU ' + gauId + ' must be greater than 0.');
            }
            total += pct;
        }

        if (total > 100) {
            throw new AllocationException('Total percentage cannot exceed 100%.');
        }

        Set<Id> gauIds = percentByGauId.keySet();
        Map<Id, npsp__General_Accounting_Unit__c> gauMap = new Map<Id, npsp__General_Accounting_Unit__c>(
            [SELECT Id, Name, npsp__Active__c FROM npsp__General_Accounting_Unit__c WHERE Id IN :gauIds]
        );

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gauMap.get(gauId);
            if (gau == null) {
                throw new AllocationException('GAU ' + gauId + ' does not exist.');
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('GAU ' + gau.Name + ' is not active.');
            }
        }

        List<npsp__Allocation__c> existing = [
            SELECT Id FROM npsp__Allocation__c WHERE npsp__Opportunity__c = :opportunityId
        ];

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            npsp__Allocation__c alloc = new npsp__Allocation__c();
            alloc.npsp__Opportunity__c = opportunityId;
            alloc.npsp__General_Accounting_Unit__c = gauId;
            alloc.npsp__Percent__c = percentByGauId.get(gauId);
            newAllocations.add(alloc);
        }

        if (!existing.isEmpty()) {
            delete existing;
        }
        insert newAllocations;

        return newAllocations;
    }
}
