public with sharing class HouseholdService {

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        Contact primary = members[0];

        // Insert the primary contact alone so NPSP's automatic household
        // creation/naming logic creates exactly one household account for it.
        insert primary;

        Id householdAccountId = [
            SELECT AccountId
            FROM Contact
            WHERE Id = :primary.Id
        ].AccountId;

        // Assign all remaining contacts to that same household account
        // and insert them together (no additional households are created
        // because we're explicitly setting AccountId).
        List<Contact> rest = new List<Contact>();
        for (Integer i = 1; i < members.size(); i++) {
            Contact c = members[i];
            c.AccountId = householdAccountId;
            rest.add(c);
        }

        if (!rest.isEmpty()) {
            insert rest;
        }

        // Set the primary contact on the household account.
        Account householdAccount = new Account(
            Id = householdAccountId,
            npe01__One2OneContact__c = primary.Id
        );
        update householdAccount;

        return householdAccountId;
    }
}
