public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId != null) oppIds.add(req.opportunityId);
            if (req.contactId != null) contactIds.add(req.contactId);
        }

        // SOQL #1: Opportunities
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
             FROM Opportunity
             WHERE Id IN :oppIds]
        );

        // Validate everything before any DML
        for (SoftCreditRequest req : requests) {
            Opportunity opp = (req.opportunityId != null) ? oppMap.get(req.opportunityId) : null;
            if (opp == null) {
                throw new SoftCreditException('Invalid Opportunity on request.');
            }
            if (req.contactId == null) {
                throw new SoftCreditException('Contact is required on request.');
            }
            if (opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException('Contact cannot be the Opportunity primary contact.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be positive.');
            }
            if (opp.Amount != null && req.amount > opp.Amount) {
                throw new SoftCreditException('Amount cannot exceed the Opportunity amount.');
            }
            if (String.isBlank(req.role)) {
                throw new SoftCreditException('Role is required on request.');
            }
        }

        // SOQL #2: existing Opportunity Contact Roles
        Map<String, List<OpportunityContactRole>> ocrByKey = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ]) {
            String key = ocr.OpportunityId + ':' + ocr.ContactId;
            if (!ocrByKey.containsKey(key)) {
                ocrByKey.put(key, new List<OpportunityContactRole>());
            }
            ocrByKey.get(key).add(ocr);
        }

        List<OpportunityContactRole> ocrUpsertList = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrDeleteList = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> chosenOcrByKey = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + ':' + req.contactId;
            if (chosenOcrByKey.containsKey(key)) {
                // same opp/contact pair repeated with a different role - not expected per spec,
                // but keep last requested role deterministic.
                OpportunityContactRole existingChosen = chosenOcrByKey.get(key);
                existingChosen.Role = req.role;
                continue;
            }

            List<OpportunityContactRole> existing = ocrByKey.get(key);
            OpportunityContactRole chosen;
            if (existing == null || existing.isEmpty()) {
                chosen = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
            } else {
                chosen = existing[0];
                chosen.Role = req.role;
                for (Integer i = 1; i < existing.size(); i++) {
                    ocrDeleteList.add(existing[i]);
                }
            }
            chosenOcrByKey.put(key, chosen);
            ocrUpsertList.add(chosen);
        }

        // DML #1: upsert contact roles (handles both insert and update)
        if (!ocrUpsertList.isEmpty()) {
            upsert ocrUpsertList;
        }

        // DML #2: remove duplicate contact roles for the same contact/opp pair
        if (!ocrDeleteList.isEmpty()) {
            delete ocrDeleteList;
        }

        // SOQL #3: existing Partial Soft Credits
        Map<String, npsp__Partial_Soft_Credit__c> pscByKey = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ]) {
            String key = psc.npsp__Opportunity__c + ':' + psc.npsp__Contact__c;
            pscByKey.put(key, psc);
        }

        Map<String, npsp__Partial_Soft_Credit__c> pscUpsertByKey = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + ':' + req.contactId;
            OpportunityContactRole ocr = chosenOcrByKey.get(key);

            npsp__Partial_Soft_Credit__c psc = pscUpsertByKey.containsKey(key)
                ? pscUpsertByKey.get(key)
                : pscByKey.get(key);

            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId
                );
            }
            psc.npsp__Amount__c = req.amount;
            psc.npsp__Role_Name__c = req.role;
            psc.npsp__Contact_Role_ID__c = ocr.Id;

            pscUpsertByKey.put(key, psc);
        }

        // DML #3: upsert partial soft credits
        if (!pscUpsertByKey.isEmpty()) {
            upsert pscUpsertByKey.values();
        }
    }
}
