public with sharing class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> allIds = new Set<Id>();
        allIds.addAll(parentIdByChildId.keySet());
        allIds.addAll(parentIdByChildId.values());

        // Single SOQL query to find any existing relationships involving any of these contacts
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allIds
               OR npe4__RelatedContact__c IN :allIds
        ]) {
            existingPairs.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) {
                continue;
            }

            String key = pairKey(childId, parentId);
            if (existingPairs.contains(key)) {
                continue;
            }

            // Mark as processed so duplicates within the same batch are also skipped
            existingPairs.add(key);

            npe4__Relationship__c rel = new npe4__Relationship__c();
            rel.npe4__Contact__c = childId;
            rel.npe4__RelatedContact__c = parentId;
            rel.npe4__Type__c = 'Parent';
            rel.npe4__Status__c = 'Current';
            toInsert.add(rel);
        }

        if (!toInsert.isEmpty()) {
            insert toInsert;
            // NPSP's own relationship trigger will automatically create the
            // reciprocal relationship record (Son/Daughter/Child) based on the
            // Relationship Lookup settings for 'Parent'.
        }
    }

    private static String pairKey(Id contactA, Id contactB) {
        // Order-independent key so either direction is detected as "existing"
        String a = String.valueOf(contactA);
        String b = String.valueOf(contactB);
        return (a < b) ? (a + ':' + b) : (b + ':' + a);
    }
}
