public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        List<FB_Employee__c> result = new List<FB_Employee__c>();

        if (!Schema.sObjectType.FB_Employee__c.isAccessible()) {
            return result;
        }

        List<String> fields = new List<String>{ 'Id', 'Name' };

        Map<String, Schema.SObjectField> fieldMap =
            Schema.sObjectType.FB_Employee__c.fields.getMap();

        List<String> candidateFields = new List<String>{
            'Department__c', 'Salary__c', 'Personal_Email__c'
        };

        for (String f : candidateFields) {
            Schema.DescribeFieldResult dfr = fieldMap.get(f).getDescribe();
            if (dfr.isAccessible()) {
                fields.add(f);
            }
        }

        String query = 'SELECT ' + String.join(fields, ', ') +
                        ' FROM FB_Employee__c ORDER BY Name ASC';

        result = Database.query(query);

        return result;
    }
}
