public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldMap = new Map<Id, SObject>(triggerOld);
        List<Task> tasksToInsert = new List<Task>();

        for (SObject newSObj : triggerNew) {
            Opportunity newOpp = (Opportunity) newSObj;
            Opportunity oldOpp = (Opportunity) oldMap.get(newOpp.Id);

            // Only act on the first time this record is seen in an afterUpdate
            // context within this transaction, so the rounding action's
            // subsequent update of the same record does not produce a
            // second task.
            Integer timesSeen = TriggerBase.idToNumberOfTimesSeenAfterUpdate.get(newOpp.Id);
            if (timesSeen != 1) {
                continue;
            }

            if (newOpp.Amount != oldOpp.Amount) {
                tasksToInsert.add(
                    new Task(
                        Subject = 'Amount changed',
                        WhatId = newOpp.Id,
                        Status = 'Completed'
                    )
                );
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
